translate this code from Rust to python:
```rust
use std::collections::HashMap;

struct AllOne {
    data: HashMap<String, u32>,
}

impl AllOne {
    fn new() -> Self {
        Self {
            data: HashMap::new(),
        }
    }

    fn inc(&mut self, key: String) {
        *self.data.entry(key).or_insert(0) += 1;
    }

    fn dec(&mut self, key: String) {
        if let Some(val) = self.data.get_mut(&key) {
            *val -= 1;
            if *val == 0 {
                self.data.remove(&key);
            }
        }
    }

    fn get_max_key(&self) -> String {
        self.data
            .iter()
            .max_by_key(|(_, v)| *v)
            .map_or(String::new(), |(k, _)| k.clone())
    }

    fn get_min_key(&self) -> String {
        self.data
            .iter()
            .min_by_key(|(_, v)| *v)
            .map_or(String::new(), |(k, _)| k.clone())
    }
}
```

