```objective-c
@interface MyQueue : NSObject

- (void)push:(int)x;
- (int)pop;
- (int)peek;
- (BOOL)empty;

@end

@implementation MyQueue {
    NSMutableArray *_stack1;
    NSMutableArray *_stack2;
}

- (instancetype)init {
    self = [super init];
    if (self) {
        _stack1 = [NSMutableArray new];
        _stack2 = [NSMutableArray new];
    }
    return self;
}

- (void)push:(int)x {
    [_stack1 addObject:@(x)];
}

- (int)pop {
    if (_stack2.count == 0) {
        while (_stack1.count > 0) {
            [_stack2 addObject:[_stack1 lastObject]];
            [_stack1 removeLastObject];
        }
    }
    int front = [[_stack2 lastObject] intValue];
    [_stack2 removeLastObject];
    return front;
}

- (int)peek {
    if (_stack2.count == 0) {
        while (_stack1.count > 0) {
            [_stack2 addObject:[_stack1 lastObject]];
            [_stack1 removeLastObject];
        }
    }
    return [[_stack2 lastObject] intValue];
}

- (BOOL)empty {
    return (_stack1.count == 0 && _stack2.count == 0);
}

@end
```

