function isReflected(points: number[][]): boolean {
    const pointSet = new Set(points.map(point => point.join(',')));
    const min_x = Math.min(...points.map(point => point[0]));
    const max_x = Math.max(...points.map(point => point[0]));
    const sum_x = min_x + max_x;
    for (const point of points) {
        const reflection = [sum_x - point[0], point[1]];
        if (!pointSet.has(reflection.join(','))) {
            return false;
        }
    }
    return true;
}
```

