function minimumCost(expression: string): number {
    const n: number = expression.length;
    const dp: number[][][] = Array.from({length: n}, () => Array.from({length: n}, () => Array.from({length: 2}, () => Infinity)));

    const evalExpr = (start: number, end: number, target: number): number => {
        if (start === end) {
            return (expression[start] === target.toString()) ? 0 : 1;
        }
        if (dp[start][end][target] !== Infinity) {
            return dp[start][end][target];
        }
        let cost: number = Infinity;
        for (let i = start; i < end; i++) {
            if (expression[i] === '&') {
                cost = Math.min(cost, evalExpr(start, i, 1) + evalExpr(i+1, end, 1-target));
                cost = Math.min(cost, evalExpr(start, i, 1-target) + evalExpr(i+1, end, 1));
            } else if (expression[i] === '|') {
                cost = Math.min(cost, evalExpr(start, i, target) + evalExpr(i+1, end, target));
                cost = Math.min(cost, evalExpr(start, i, target) + evalExpr(i+1, end, 1-target));
                cost = Math.min(cost, evalExpr(start, i, 1-target) + evalExpr(i+1, end, target));
            }
        }
        dp[start][end][target] = cost;
        return cost;
    }

    return evalExpr(0, n-1, 0);
}
